const $ = (id) => document.getElementById(id);
const ui = {
  user: $("user"), key: $("key"), question: $("question"), runState: $("run-state"),
  statusHeading: $("status-heading"), statusBadge: $("status-badge"), statusMessage: $("status-message"),
  progress: $("progress-list"), progressBar: $("progress-bar"), graphPanel: $("graph-panel"), graph: $("graph"),
  summaryGrid: $("summary-grid"), overview: $("overview"), comparison: $("comparison"), ethicsPanel: $("ethics-panel"), ethics: $("ethics"),
  evidencePanel: $("evidence-panel"), evidence: $("evidence"), evidenceCount: $("evidence-count"),
  revisionsPanel: $("revisions-panel"), revisions: $("revisions"), timelinePanel: $("timeline-panel"), timeline: $("timeline"),
  approvalPanel: $("approval-panel"), approvalHeading: $("approval-heading"), approvalSummary: $("approval-summary"),
  exportsPanel: $("exports-panel"), recovery: $("recovery-actions"), announcer: $("announcer"), connection: $("connection"),
  dialog: $("decision-dialog"), dialogTitle: $("dialog-title"), dialogDescription: $("dialog-description"),
  consequences: $("decision-consequences"), feedback: $("feedback"), toast: $("toast"),
  toastMessage: $("toast-message"), toastUndo: $("toast-undo"), recentRuns: $("recent-runs"),
  uncertainty: $("uncertainty"), compareRun: $("compare-run"), historyVersion: $("history-version"),
  scorecard: $("scorecard"), traceability: $("traceability"), disagreements: $("disagreements"), beforeAfter: $("before-after")
};

let threadId = "", latest = null, stream = null, decisionKind = "protocol", technicalNames = false;
let graphZoom = 1, toastTimer = null, previousReviewState = false;
let lastAnnouncement = "";
let recorder = null, audioChunks = [], liveSocket = null, audioContext = null, processor = null, liveText = "", localRecognition = null;

const demoQuestions = [
  ["AI education","Does an AI tutor improve algebra transfer for first-year students?"],
  ["RAG safety","Does retrieval-augmented generation reduce hallucinations in technical support answers?"],
  ["Engineering","Can protected focus time reduce software-engineer burnout without lowering delivery quality?"],
  ["Security","Does AI-assisted code review detect more access-control vulnerabilities than standard review?"],
  ["Learning science","Does spaced retrieval improve cybersecurity certification retention after eight weeks?"],
  ["Wellbeing","Can short movement breaks reduce afternoon fatigue among remote data scientists?"],
  ["AI evaluation","Can source reranking reduce unsupported claims in retrieval-augmented legal summaries?"],
  ["Developer tools","Does an AI tutor improve Python debugging skills for novice programmers?"]
];

const nodeNames = {
  research_planner: "Research Planner", evidence_worker: "Evidence Researchers", evidence_gate: "Evidence Verifier",
  fallback_evidence: "Fallback Evidence", hypothesis_scientist: "Hypothesis Scientist", methods_designer: "Methods Designer",
  ethics_reviewer: "Ethics Reviewer", ethics_human_review: "Human Ethics Review", ethics_revision_editor: "Ethics Revision",
  statistician: "Statistician", skeptical_reviewer: "Skeptical Reviewer", revision_editor: "Revision Editor",
  protocol_synthesizer: "Protocol Synthesizer", human_approval: "Human Approval", complete: "Complete"
};
const graphNodes = {
  research_planner:[70,170], evidence_worker:[220,85], evidence_gate:[365,85], fallback_evidence:[365,245],
  hypothesis_scientist:[510,170], methods_designer:[650,170], ethics_reviewer:[790,100], ethics_human_review:[930,45],
  ethics_revision_editor:[930,155], statistician:[790,260], skeptical_reviewer:[650,300], revision_editor:[510,300],
  protocol_synthesizer:[365,300], human_approval:[220,300], complete:[70,300]
};
const edges = [
  ["research_planner","evidence_worker"],["evidence_worker","evidence_gate"],["evidence_gate","hypothesis_scientist"],
  ["evidence_gate","fallback_evidence"],["fallback_evidence","hypothesis_scientist"],["hypothesis_scientist","methods_designer"],
  ["methods_designer","ethics_reviewer"],["ethics_reviewer","ethics_human_review"],["ethics_human_review","ethics_revision_editor"],
  ["ethics_revision_editor","ethics_reviewer"],["ethics_reviewer","statistician"],["statistician","skeptical_reviewer"],
  ["skeptical_reviewer","revision_editor"],["revision_editor","skeptical_reviewer"],["skeptical_reviewer","protocol_synthesizer"],
  ["protocol_synthesizer","human_approval"],["human_approval","revision_editor"],["human_approval","complete"]
];
const stages = [
  ["Planning",["research_planner"]],["Evidence",["evidence_worker","evidence_gate","fallback_evidence"]],
  ["Hypothesis",["hypothesis_scientist"]],["Study design",["methods_designer"]],["Ethics",["ethics_reviewer","ethics_human_review","ethics_revision_editor"]],
  ["Statistics",["statistician"]],["Peer review",["skeptical_reviewer","revision_editor"]],["Approval",["protocol_synthesizer","human_approval","complete"]]
];

function apiHeaders(json=true){const headers={"X-ResearchGuard-User":ui.user.value,"X-ResearchGuard-Key":ui.key.value};if(json)headers["content-type"]="application/json";return headers}
function escapeHtml(value){return String(value??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]))}
function safeExternalUrl(value){try{const url=new URL(String(value));return ["http:","https:"].includes(url.protocol)?url.href:"#"}catch{return"#"}}
function showToast(message,undo=null){clearTimeout(toastTimer);ui.toastMessage.textContent=message;ui.toastUndo.hidden=!undo;ui.toastUndo.onclick=async()=>{ui.toast.hidden=true;await undo?.()};ui.toast.hidden=false;toastTimer=setTimeout(()=>ui.toast.hidden=true,5000)}
function announce(message){if(message===lastAnnouncement)return;lastAnnouncement=message;ui.announcer.textContent=message}
async function request(url,options={}){const response=await fetch(url,options);if(!response.ok){let message=`Request failed (${response.status})`;try{message=(await response.json()).detail||message}catch{}if(response.status===401)message="Authentication failed. Check the API key in Connection settings.";if(response.status===429)message="Too many requests. Wait briefly and try again.";throw new Error(message)}return response}

async function startRun(showcase=false){resetView();setConnection("working","Connecting agents…");try{const response=await request(showcase?"/api/showcase":"/api/runs",{method:"POST",headers:apiHeaders(),body:showcase?undefined:JSON.stringify({question:ui.question.value,background:true})});const data=await response.json();threadId=data.thread_id;render(data);openStream();loadRuns()}catch(error){renderError(error.message)}}
function openStream(){closeStream();const query=new URLSearchParams({user:ui.user.value,key:ui.key.value});stream=new EventSource(`/api/runs/${threadId}/events?${query}`);stream.onopen=()=>setConnection("connected","Live updates connected");stream.onmessage=(event)=>{const data=JSON.parse(event.data);render(data);if(isTerminal(data))closeStream()};stream.onerror=()=>{setConnection("warning","Live updates reconnecting…")}}
function closeStream(){if(stream){stream.close();stream=null}}
function isTerminal(data){return data.state?.status==="complete"||["failed","cancelled"].includes(data.job_status)||(data.next||[]).some(node=>node.includes("human_review")||node==="human_approval")}
function setConnection(kind,text){ui.connection.className=`connection ${kind}`;ui.connection.innerHTML=`<span></span>${escapeHtml(text)}`}
function resetView(){[ui.summaryGrid,ui.ethicsPanel,ui.evidencePanel,ui.revisionsPanel,ui.timelinePanel,ui.approvalPanel,ui.exportsPanel,ui.recovery].forEach(el=>el.hidden=true);ui.runState.hidden=false;ui.graphPanel.hidden=false;ui.statusHeading.textContent="Starting";ui.statusMessage.textContent="Preparing the research council…";ui.comparison.innerHTML=""}
function renderError(message){ui.runState.hidden=false;ui.statusHeading.textContent="Unable to continue";ui.statusBadge.textContent="Failed";ui.statusMessage.textContent=message;ui.recovery.hidden=false;setConnection("failed","Action required");announce(message)}
function selectDemoQuestion(index){
  const normalized=((index%demoQuestions.length)+demoQuestions.length)%demoQuestions.length;
  ui.question.value=demoQuestions[normalized][1];
  localStorage.setItem("rg-demo-question-index",String(normalized));
  $("demo-question-options").querySelectorAll("button").forEach((button,i)=>button.setAttribute("aria-pressed",String(i===normalized)));
  ui.question.focus();
  announce(`${demoQuestions[normalized][0]} example selected.`);
}
function setupDemoQuestions(){
  const container=$("demo-question-options");
  container.innerHTML=demoQuestions.map(([domain,question],index)=>`<button type="button" data-demo-question="${index}" aria-pressed="false"><span>${escapeHtml(domain)}</span><small>${escapeHtml(question)}</small></button>`).join("");
  container.querySelectorAll("[data-demo-question]").forEach(button=>button.onclick=()=>selectDemoQuestion(Number(button.dataset.demoQuestion)));
  $("next-demo-question").onclick=()=>{const current=Number(localStorage.getItem("rg-demo-question-index")??-1);selectDemoQuestion(current+1)};
}

function render(data){latest=data;threadId=data.thread_id||threadId;const state=data.state||{};ui.runState.hidden=false;ui.graphPanel.hidden=false;$("section-nav").hidden=false;renderStatus(data,state);renderProgress(data,state);renderGraph(data,state);renderTimeline(state);renderRecovery(data,state);if(state.ethics)renderEthics(state.ethics);if(state.protocol){renderOverview(state.protocol);renderScorecard(state);renderEvidence(state.protocol.evidence||[]);renderTraceability(state.protocol);renderDisagreements(state.protocol);renderBeforeAfter(state.protocol);renderRevisions(state.protocol.revision_history||[]);renderComparison();renderComments();loadHistory();ui.exportsPanel.hidden=false}renderApproval(data,state);applyRunFilters();applyWorkspaceView();updateInbox(data,state)}
function renderStatus(data,state){const next=data.next||[],status=state.status||data.job_status||"starting";ui.statusHeading.textContent=window.rgT(status)||status.replaceAll("_"," ");ui.statusBadge.textContent=window.rgT(data.job_status||status);let message="Agents are working through the research plan.";if(next.includes("ethics_human_review"))message="A consequential ethics decision requires human review.";else if(next.includes("human_approval"))message="The protocol is ready for final review.";else if(state.warnings?.length)message=state.warnings.at(-1);else if(status==="complete")message="The approved protocol and audit record are ready.";ui.statusMessage.textContent=message;announce(`${ui.statusHeading.textContent}. ${message}`);setConnection(status==="complete"?"connected":"working",status==="complete"?window.rgT("completed"):"Council active")}
function eventBases(state){return new Set((state.events||[]).map(event=>event.node.split(":")[0]))}
function renderProgress(data,state){const done=eventBases(state),active=new Set(data.next||[]);let completed=0;ui.progress.innerHTML=stages.map(([label,nodes])=>{const isDone=nodes.some(n=>done.has(n))&&!nodes.some(n=>active.has(n));const isActive=nodes.some(n=>active.has(n));if(isDone)completed++;return `<li class="${isDone?'done':isActive?'active':''}"><strong>${escapeHtml(label)}</strong><br><span class="muted">${isDone?'Complete':isActive?'In progress':'Waiting'}</span></li>`}).join("");ui.progressBar.style.width=`${Math.round(completed/stages.length*100)}%`;recordObservedTimings(state);const terminal=isTerminal(data),seconds=estimateRemainingSeconds(done);$("progress-estimate").textContent=terminal?"Workflow paused or complete · your input may be required":`${completed} of ${stages.length} stages complete · estimated ${seconds}–${Math.max(seconds+1,Math.ceil(seconds*1.6))} seconds remaining based on observed runs`;$("mobile-progress").innerHTML=ui.progress.innerHTML}
function renderGraph(data,state){const done=eventBases(state),active=new Set(data.next||[]),failed=new Set((state.events||[]).filter(e=>e.status!=="completed").map(e=>e.node.split(":")[0]));const edgeSvg=edges.map(([a,b])=>{const [x1,y1]=graphNodes[a],[x2,y2]=graphNodes[b];const activeEdge=done.has(a)&&active.has(b);return `<path class="edge ${activeEdge?'active':''}" d="M ${x1} ${y1} C ${(x1+x2)/2} ${y1}, ${(x1+x2)/2} ${y2}, ${x2} ${y2}"/>`}).join("");const nodeSvg=Object.entries(graphNodes).map(([name,[x,y]])=>`<g data-node="${name}" tabindex="0" role="button" aria-label="Inspect ${escapeHtml(nodeNames[name]||name)}" class="${done.has(name)?'done':''} ${active.has(name)?'active':''} ${failed.has(name)?'failed':''}" transform="translate(${x-55},${y-22})"><rect class="node-box" width="110" height="44" rx="10"/><text x="55" y="19">${escapeHtml(technicalNames?name:(nodeNames[name]||name)).slice(0,21)}</text><text x="55" y="34" class="muted">${active.has(name)?'Active':done.has(name)?'Done':'Waiting'}</text></g>`).join("");ui.graph.innerHTML=`<svg viewBox="0 0 1000 360" aria-hidden="true" style="transform:scale(${graphZoom})"><defs><marker id="arrow" markerWidth="8" markerHeight="8" refX="7" refY="4" orient="auto"><path d="M0,0 L8,4 L0,8 z" fill="#526d8b"/></marker></defs>${edgeSvg}${nodeSvg}</svg>`;ui.graph.querySelectorAll("[data-node]").forEach(el=>{el.onclick=()=>inspectNode(el.dataset.node);el.onkeydown=e=>{if(e.key==="Enter"||e.key===" ")inspectNode(el.dataset.node)}})}

function renderOverview(protocol){ui.summaryGrid.hidden=false;const values=[["Study design",protocol.study.design],["Population",protocol.study.population],["Intervention",protocol.study.intervention],["Comparator",protocol.study.comparator],["Primary outcome",protocol.study.outcome],["Enrollment",protocol.statistics.target_sample_size],["Duration",protocol.study.duration],["Ethics risk",protocol.ethics.risk_level]];ui.overview.innerHTML=values.map(([label,value])=>`<div class="metric"><span>${escapeHtml(label)}</span><strong>${escapeHtml(value)}</strong></div>`).join("");const evidence=protocol.evidence||[],mean=k=>evidence.length?evidence.reduce((n,x)=>n+Number(x[k]||0),0)/evidence.length:0,risks=(protocol.unresolved_risks||[]).length;ui.uncertainty.innerHTML=`<h3>Uncertainty signals</h3>${uncertaintyRow("Evidence verified",evidence.length?evidence.filter(x=>x.verified).length/evidence.length:0)}${uncertaintyRow("Mean support",mean("entailment_score"))}${uncertaintyRow("Mean relevance",mean("relevance_score"))}<p class="${risks?'risk':'muted'}">${risks?`${risks} unresolved risk${risks===1?'':'s'} require attention.`:'No unresolved risks recorded.'}</p>`}
function uncertaintyRow(label,value){const pct=Math.round(value*100);return `<div class="uncertainty-row"><span>${escapeHtml(label)}</span><div class="meter"><i style="width:${pct}%"></i></div><strong>${pct}%</strong></div>`}
async function renderComparison(){try{const response=await request(`/api/runs/${threadId}/comparison`,{headers:apiHeaders(false)});const {single_agent:a,researchguard:g}=await response.json();const rows=[["Verified evidence",`${Math.round(a.verified_evidence_rate*100)}%`,`${Math.round(g.verified_evidence_rate*100)}%`],["High-risk defects",a.unresolved_high_risks,g.unresolved_high_risks],["Revision cycles",a.revision_count,g.revision_count],["Human governance",a.requires_approval?"Yes":"No",g.requires_approval?"Yes":"No"]];ui.comparison.innerHTML=`<table class="comparison-table"><thead><tr><th>Metric</th><th>Single agent</th><th>ResearchGuard</th></tr></thead><tbody>${rows.map(row=>`<tr><td>${row[0]}</td><td>${row[1]}</td><td class="winner">${row[2]}</td></tr>`).join("")}</tbody></table>`}catch(error){ui.comparison.innerHTML=`<p class="muted">${escapeHtml(error.message)}</p>`}}
function renderEthics(ethics){ui.ethicsPanel.hidden=false;const findings=ethics.findings||[];ui.ethics.innerHTML=`<div class="metric"><span>Risk level</span><strong>${escapeHtml(ethics.risk_level)}</strong></div>${findings.length?findings.map(item=>`<div class="risk"><strong>${escapeHtml(item.issue)}</strong><p>${escapeHtml(item.recommendation)}</p></div>`).join(""):'<p>No elevated ethics risks detected by the automated review.</p>'}`}

function sourceType(item){if(item.source?.startsWith("demo://"))return"demo";if(item.identifier?.startsWith("PMID"))return"pubmed";if(item.identifier?.startsWith("DOI"))return"crossref";return"other"}
function scoreLabel(score){return score>=.75?"High":score>=.45?"Moderate":"Low"}
function renderEvidence(items){ui.evidencePanel.hidden=false;const source=$("source-filter").value,verification=$("verified-filter").value,sort=$("evidence-sort").value,bookmarks=getBookmarks();let filtered=items.filter(item=>(source==="all"||sourceType(item)===source)&&(verification==="all"||(verification==="verified")===Boolean(item.verified)));filtered.sort((a,b)=>sort==="title"?a.title.localeCompare(b.title):sort==="support"?b.entailment_score-a.entailment_score:b.relevance_score-a.relevance_score);ui.evidenceCount.textContent=`${filtered.length} of ${items.length}`;ui.evidence.innerHTML=filtered.length?filtered.map((item,index)=>{const type=sourceType(item),synthetic=type==="demo",key=evidenceKey(item),saved=bookmarks.includes(key),safeSource=safeExternalUrl(item.source);return `<details class="evidence-card" data-resolved="${item.verified}"><summary><div><span class="source-badge ${synthetic?'synthetic':''}">${synthetic?'Synthetic demonstration source':type}</span><h3>${escapeHtml(item.title)}</h3><p>${escapeHtml(item.claim||item.finding)}</p></div><span aria-label="${item.verified?'Verified':'Needs review'}">${item.verified?'✓ Verified':'⚠ Review'}</span></summary><div class="evidence-body"><p><strong>Supporting passage</strong><br>${escapeHtml(item.supporting_passage||'No supporting passage extracted.')}</p><div class="score-row">${scoreMeter('Support',item.entailment_score)}${scoreMeter('Relevance',item.relevance_score)}</div><div class="actions">${safeSource==="#"?'<span class="badge">External link unavailable</span>':`<a href="${escapeHtml(safeSource)}" target="_blank" rel="noopener noreferrer">Open source</a>`}<button data-provenance="${index}">View provenance</button><button class="bookmark" data-bookmark="${escapeHtml(key)}" aria-pressed="${saved}" aria-label="${saved?'Remove bookmark':'Bookmark evidence'}">${saved?'★':'☆'}</button><button data-comment-evidence="${escapeHtml(key)}">Comment</button></div>${synthetic?'<div class="notice">This source exists only to exercise the offline workflow. It is not real-world scientific evidence.</div>':''}</div></details>`}).join(""):'<div class="empty-state"><strong>No evidence matches</strong><span>Clear filters or broaden the verification requirement.</span></div>';ui.evidence.querySelectorAll("[data-provenance]").forEach(button=>button.onclick=()=>showProvenance(filtered[Number(button.dataset.provenance)]));ui.evidence.querySelectorAll("[data-bookmark]").forEach(button=>button.onclick=()=>toggleBookmark(button.dataset.bookmark));ui.evidence.querySelectorAll("[data-comment-evidence]").forEach(button=>button.onclick=()=>{$("comment-target").value="evidence";$("comment-text").focus();$("review-comments-panel").scrollIntoView()});applyRunFilters()}
function scoreMeter(label,score){return `<div class="score-meter"><span>${label}: ${scoreLabel(score)} · ${Number(score).toFixed(2)}</span><div class="meter" role="meter" aria-label="${label}" aria-valuemin="0" aria-valuemax="1" aria-valuenow="${score}"><i style="width:${score*100}%"></i></div></div>`}

function renderTimeline(state){const events=state.events||[];if(!events.length)return;ui.timelinePanel.hidden=false;const groups={};for(const event of events){const base=event.node.split(":")[0],group=base==="evidence_worker"?"Evidence collection":nodeNames[base]||base;(groups[group]??=[]).push(event)}ui.timeline.innerHTML=Object.entries(groups).map(([name,values])=>`<details class="timeline-group" open><summary>${escapeHtml(name)} — ${values.length} event${values.length===1?'':'s'}</summary>${values.map(event=>`<div class="event"><span aria-hidden="true">${event.status==='failed'?'✕':event.status==='warning'?'⚠':'✓'}</span> ${escapeHtml(event.message)}<br><time>${formatTime(event.timestamp)}${event.duration_ms!=null?` · ${formatDuration(event.duration_ms)}`:''}</time></div>`).join("")}</details>`).join("")}
function formatTime(value){if(!value)return"";return new Intl.DateTimeFormat(undefined,{hour:"numeric",minute:"2-digit",second:"2-digit"}).format(new Date(value))}
function formatDuration(ms){return ms<1000?`${Math.round(ms)} ms`:`${(ms/1000).toFixed(1)} s`}
function renderRevisions(records){ui.revisionsPanel.hidden=false;ui.revisions.innerHTML=records.length?records.map(record=>{let before={},after={};try{before=JSON.parse(record.before);after=JSON.parse(record.after)}catch{return `<div class="diff-field"><strong>Revision ${record.revision}</strong><p>${escapeHtml(record.reason)}</p></div>`}const fields=new Set([...Object.keys(before),...Object.keys(after)]);return `<details open><summary><strong>Revision ${record.revision}</strong> — ${escapeHtml(record.reason)}</summary>${[...fields].filter(key=>JSON.stringify(before[key])!==JSON.stringify(after[key])).map(key=>`<div class="diff-field"><strong>${escapeHtml(key.replaceAll('_',' '))}</strong><div class="before">− ${escapeHtml(JSON.stringify(before[key]))}</div><div class="after">+ ${escapeHtml(JSON.stringify(after[key]))}</div></div>`).join('')}</details>`}).join(""):'<p class="muted">No revisions were required.</p>'}

function renderApproval(data,state){const ethics=data.next?.includes("ethics_human_review"),protocol=data.next?.includes("human_approval");ui.approvalPanel.hidden=!(ethics||protocol);if(ethics||protocol){decisionKind=ethics?"ethics":"protocol";ui.approvalHeading.textContent=ethics?"Ethics review required":"Protocol approval required";ui.approvalSummary.textContent=ethics?"Review the identified participant risks and mandatory safeguards before research continues.":"Review the evidence, methods, ethics assessment, and unresolved risks before finalizing the protocol.";renderReadiness(state)}reviewNotification()}
function renderRecovery(data,state){const hasFailures=(state.tool_failures||[]).length>0,failed=["failed","cancelled"].includes(data.job_status);ui.recovery.hidden=!(hasFailures||failed||data.job_status==="running");$("retry-button").hidden=!hasFailures;$("offline-button").hidden=!hasFailures;$("continue-button").hidden=!hasFailures;$("cancel-button").hidden=data.job_status!=="running"}
async function recovery(action){try{const response=await request(`/api/runs/${threadId}/recovery`,{method:"POST",headers:apiHeaders(),body:JSON.stringify({action})});const data=await response.json();if(data.thread_id&&data.thread_id!==threadId){threadId=data.thread_id;render(data);openStream()}else if(action==="continue")ui.recovery.hidden=true;else render(data);showToast(action==="offline"?"Started an offline evidence run.":action==="retry"?"Started a replacement run.":"Cancellation requested.")}catch(error){showToast(error.message)}}

function openDecision(approve){ui.dialogTitle.textContent=decisionKind==="ethics"?"Review ethics safeguards":"Review final protocol";ui.dialogDescription.textContent=decisionKind==="ethics"?"Your decision will be recorded and required safeguards will be added before the workflow resumes.":"Approval finalizes the protocol. Requesting changes sends your exact feedback to the revision agent.";ui.consequences.textContent=approve?"Approval resumes the graph and records your decision in the audit history.":"Requested changes will create another revision cycle. Be specific so the resulting diff is verifiable.";ui.feedback.value="";$("submit-approval").hidden=!approve;$("submit-changes").hidden=approve;ui.dialog.showModal();setTimeout(()=>ui.feedback.focus(),0)}
async function submitDecision(approved){const feedback=ui.feedback.value.trim();if(!approved&&!feedback){showToast("Describe the required change before continuing.");ui.feedback.focus();return}try{const response=await request(`/api/runs/${threadId}/decision`,{method:"POST",headers:apiHeaders(),body:JSON.stringify({approved,feedback})});ui.dialog.close();const data=await response.json();render(data);if(!isTerminal(data))openStream();showToast(approved?"Decision approved and recorded.":"Revision requested.")}catch(error){showToast(error.message)}}
function browserRecognition(){const Recognition=window.SpeechRecognition||window.webkitSpeechRecognition;if(!Recognition)throw new Error("Browser transcription is unavailable. Use Safari or Chrome, or configure a server voice provider.");return new Recognition()}
function stopLocalRecognition(){if(localRecognition){localRecognition.onend=null;localRecognition.stop();localRecognition=null}}
function startLocalRecognition(onText){const recognition=browserRecognition();recognition.continuous=true;recognition.interimResults=true;recognition.lang=navigator.language||"en-US";recognition.onresult=event=>{let transcript="";for(const result of event.results)transcript+=result[0].transcript;onText(transcript,event)};recognition.onerror=event=>{if(event.error!=="aborted")showToast(`Browser transcription unavailable: ${event.error}`)};recognition.start();localRecognition=recognition;return recognition}
async function speak(){const text=JSON.stringify(latest.state.protocol,null,2).slice(0,8000);if("speechSynthesis" in window){window.speechSynthesis.cancel();const utterance=new SpeechSynthesisUtterance(text);utterance.rate=.95;window.speechSynthesis.speak(utterance);return}try{const response=await request("/api/voice/briefing",{method:"POST",headers:apiHeaders(),body:JSON.stringify({protocol:latest.state.protocol})});new Audio(URL.createObjectURL(await response.blob())).play()}catch(error){showToast(error.message)}}
async function exportReport(){try{const response=await request(`/api/runs/${threadId}/report.md`,{headers:apiHeaders(false)});const link=document.createElement("a");link.href=URL.createObjectURL(await response.blob());link.download=`researchguard-${threadId}.md`;link.click()}catch(error){showToast(error.message)}}
async function toggleRecording(){if(recorder?.state==="recording"){recorder.stop();stopLocalRecognition();$("record-button").textContent="Record question";return}try{const media=await navigator.mediaDevices.getUserMedia({audio:true});audioChunks=[];recorder=new MediaRecorder(media);recorder.ondataavailable=e=>audioChunks.push(e.data);recorder.onstop=()=>media.getTracks().forEach(track=>track.stop());const recognition=startLocalRecognition(transcript=>{ui.question.value=transcript});recognition.onend=()=>{if(recorder?.state==="recording")try{recognition.start()}catch{}};recorder.start();$("record-button").textContent="Stop and transcribe"}catch(error){showToast(`Microphone or browser transcription unavailable: ${error.message}`)}}
async function toggleLive(){if(localRecognition){stopLocalRecognition();$("live-button").textContent="Live dictation";return}try{liveText=ui.question.value.trim();const recognition=startLocalRecognition(transcript=>{ui.question.value=liveText+(liveText&&transcript?" ":"")+transcript});recognition.onend=()=>{if(localRecognition===recognition)try{recognition.start()}catch{}};$("live-button").textContent="Stop live dictation"}catch(error){showToast(`Browser transcription unavailable: ${error.message}`)}}

function researchDomain(question=""){
  const text=question.toLowerCase();
  if(text.includes("hallucination")||text.includes("retrieval-augmented"))return"RAG safety";
  if(text.includes("security")||text.includes("code review"))return"Software security";
  if(text.includes("burnout")||text.includes("focus time"))return"Developer wellbeing";
  if(text.includes("spaced retrieval")||text.includes("certification"))return"Learning science";
  if(text.includes("exercise")||text.includes("mood"))return"Workplace wellbeing";
  if(text.includes("tutor")||text.includes("algebra"))return"AI in education";
  return"Custom research";
}
function recentRunCards(list){
  const totals=new Map();
  list.forEach(run=>{const key=(run.question||"Untitled research").trim().toLowerCase();totals.set(key,(totals.get(key)||0)+1)});
  const occurrences=new Map();
  return list.map(run=>{
    const question=run.question||"Untitled research",key=question.trim().toLowerCase();
    const occurrence=(occurrences.get(key)||0)+1;occurrences.set(key,occurrence);
    const duplicate=totals.get(key)>1?` · Version ${occurrence} of ${totals.get(key)}`:"";
    const shortId=`RG-${String(run.thread_id||"").replaceAll("-","").slice(0,8).toUpperCase()}`;
    const id=escapeHtml(run.thread_id||"");
    return `<article class="recent-run" data-run-id="${id}"><div class="recent-run-meta"><span class="study-id">${escapeHtml(shortId)}</span><span class="badge">${escapeHtml(researchDomain(question))}</span></div><h3>${escapeHtml(question)} <span class="question-run-id">— ${escapeHtml(shortId)}</span></h3><p class="muted"><strong>${escapeHtml(run.status||"unknown")}</strong>${duplicate} · Updated ${formatTime(run.updated_at||run.created_at)}</p><div class="actions wrap"><button data-resume="${id}">Resume</button><button data-copy="${id}">Copy link</button><button data-archive="${id}" data-value="${!run.archived}">${run.archived?'Restore':'Archive'}</button><button class="danger" data-delete="${id}">Delete</button></div></article>`;
  }).join("");
}
async function loadRuns(){try{const archived=$("show-archived").checked;const response=await request(`/api/runs?include_archived=${archived}`,{headers:apiHeaders(false)}),runs=await response.json();const list=Array.isArray(runs)?runs:runs.runs||[];ui.recentRuns.innerHTML=list.length?recentRunCards(list):'<p class="muted">No saved research runs yet.</p>';bindRunActions();const selected=ui.compareRun.value;ui.compareRun.innerHTML='<option value="baseline">Single-agent baseline</option>'+list.filter(r=>r.thread_id!==threadId).map(r=>`<option value="${r.thread_id}">${escapeHtml(r.question||r.thread_id)}</option>`).join("");ui.compareRun.value=[...ui.compareRun.options].some(o=>o.value===selected)?selected:"baseline"}catch(error){ui.recentRuns.innerHTML=`<p class="muted">${escapeHtml(error.message)}</p>`}}
function bindRunActions(){ui.recentRuns.querySelectorAll("[data-resume]").forEach(b=>b.onclick=()=>resumeRun(b.dataset.resume));ui.recentRuns.querySelectorAll("[data-copy]").forEach(b=>b.onclick=()=>copyRunLink(b.dataset.copy));ui.recentRuns.querySelectorAll("[data-archive]").forEach(b=>b.onclick=()=>archiveRun(b.dataset.archive,b.dataset.value==="true"));ui.recentRuns.querySelectorAll("[data-delete]").forEach(b=>b.onclick=()=>deleteRun(b.dataset.delete))}
async function resumeRun(id){try{closeStream();const response=await request(`/api/runs/${id}`,{headers:apiHeaders(false)}),data=await response.json();threadId=id;render(data);if(!isTerminal(data))openStream();location.hash="run-state"}catch(error){showToast(error.message)}}
async function archiveRun(id,archived){try{await request(`/api/runs/${id}/archive`,{method:"POST",headers:apiHeaders(),body:JSON.stringify({archived})});loadRuns();showToast(archived?"Run archived.":"Run restored.",()=>archiveRun(id,!archived))}catch(error){showToast(error.message)}}
async function deleteRun(id){if(!confirm("Permanently delete this run and its saved state?"))return;try{await request(`/api/runs/${id}`,{method:"DELETE",headers:apiHeaders(false)});if(id===threadId){closeStream();threadId="";latest=null;$("section-nav").hidden=true}loadRuns();showToast("Run deleted.")}catch(error){showToast(error.message)}}
async function copyRunLink(id){const url=`${location.origin}${location.pathname}?run=${encodeURIComponent(id)}`;try{await navigator.clipboard.writeText(url);showToast("Resume link copied.")}catch{showToast(url)}}

async function inspectNode(name){if(!threadId)return;try{const response=await request(`/api/runs/${threadId}/nodes/${name}`,{headers:apiHeaders(false)}),data=await response.json();$("node-title").textContent=nodeNames[name]||name;$("node-content").innerHTML=`<p><span class="badge">${escapeHtml(data.status||"Not started")}</span></p><p>${escapeHtml(data.description||"Agent state and artifacts for this graph node.")}</p><h3>Events</h3>${(data.events||[]).map(e=>`<div class="event">${escapeHtml(e.message)} <time>${formatDuration(e.duration_ms||0)}</time></div>`).join("")||'<p class="muted">No events yet.</p>'}<details><summary>Artifact snapshot</summary><pre>${escapeHtml(JSON.stringify(data.artifact??{},null,2))}</pre></details>`;$("node-dialog").showModal()}catch(error){showToast(error.message)}}
function showProvenance(item){if(!item)return;const steps=[["Research source",item.source],["Identifier",item.identifier||"Not supplied"],["Extracted passage",item.supporting_passage||"Not supplied"],["Claim comparison",item.claim||item.finding||"Not supplied"],["Verification outcome",item.verified?"Verified for screening":"Requires human review"]];$("provenance-steps").innerHTML=steps.map(([a,b])=>`<li><strong>${escapeHtml(a)}</strong><span>${escapeHtml(b)}</span></li>`).join("");$("provenance-dialog").showModal()}

function openProtocolEditor(){const p=latest?.state?.protocol;if(!p)return;const fields=[["population","Population",p.study.population],["intervention","Intervention",p.study.intervention],["comparator","Comparator",p.study.comparator],["outcome","Primary outcome",p.study.outcome],["duration","Duration",p.study.duration],["target_sample_size","Target enrollment",p.statistics.target_sample_size]];$("edit-fields").innerHTML=fields.map(([id,label,value])=>`<label>${label}<input name="${id}" value="${escapeHtml(value)}" ${id==="target_sample_size"?'type="number" min="1"':''}></label>`).join("");$("edit-dialog").showModal()}
async function saveProtocolEdits(){const form=new FormData($("edit-form")),body=Object.fromEntries(form.entries());body.target_sample_size=Number(body.target_sample_size);try{const response=await request(`/api/runs/${threadId}/protocol`,{method:"PATCH",headers:apiHeaders(),body:JSON.stringify(body)}),data=await response.json();$("edit-dialog").close();render(data);if(!isTerminal(data))openStream();showToast("Edits saved and sent for re-review.")}catch(error){showToast(error.message)}}
async function loadHistory(){if(!threadId)return;try{const response=await request(`/api/runs/${threadId}/history`,{headers:apiHeaders(false)}),data=await response.json(),items=Array.isArray(data)?data:data.history||[];ui.historyVersion.innerHTML='<option value="latest">Latest</option>'+items.map((x,i)=>`<option value="${i}">Revision ${escapeHtml(x.revision??i+1)}</option>`).join("");ui.historyVersion._items=items}catch{}}
function showHistoryVersion(){if(ui.historyVersion.value==="latest"){latest?.state?.protocol&&renderOverview(latest.state.protocol);return}const item=ui.historyVersion._items?.[Number(ui.historyVersion.value)];if(!item)return;let protocol=item.protocol||item.after;try{if(typeof protocol==="string")protocol=JSON.parse(protocol)}catch{}if(protocol?.study)renderOverview(protocol);else ui.comparison.innerHTML=`<div class="notice">Revision ${escapeHtml(item.revision)}: ${escapeHtml(item.reason||"Protocol update")}</div>`}
async function renderRunComparison(){if(ui.compareRun.value==="baseline")return renderComparison();try{const response=await request(`/api/compare?left=${threadId}&right=${ui.compareRun.value}`,{headers:apiHeaders(false)}),data=await response.json(),keys=new Set([...Object.keys(data.left||{}),...Object.keys(data.right||{})]);ui.comparison.innerHTML=`<table class="comparison-table"><thead><tr><th>Metric</th><th>Current</th><th>Compared run</th></tr></thead><tbody>${[...keys].map(k=>`<tr><td>${escapeHtml(k.replaceAll('_',' '))}</td><td>${escapeHtml(data.left?.[k])}</td><td>${escapeHtml(data.right?.[k])}</td></tr>`).join("")}</tbody></table>`}catch(error){ui.comparison.innerHTML=`<p class="muted">${escapeHtml(error.message)}</p>`}}

function applyRunFilters(){const q=$("run-search").value.trim().toLowerCase(),unresolved=$("unresolved-only").checked;document.querySelectorAll(".evidence-card,.timeline-group").forEach(el=>{el.classList.toggle("search-hidden",Boolean(q)&&!el.textContent.toLowerCase().includes(q));el.classList.toggle("unresolved-hidden",unresolved&&el.matches('.evidence-card[data-resolved="true"]'))})}
function setTheme(theme){document.documentElement.dataset.theme=theme==="system"?"":theme;$("theme-button").textContent=`Theme: ${theme}`;localStorage.setItem("rg-theme",theme)}
function cycleTheme(){const themes=["system","dark","light"],current=localStorage.getItem("rg-theme")||"system";setTheme(themes[(themes.indexOf(current)+1)%themes.length])}
function reviewNotification(){const required=(latest?.next||[]).some(x=>x.includes("human_review")||x==="human_approval");if(required&&!previousReviewState){if($("notify-review").checked&&Notification.permission==="granted")new Notification("ResearchGuard review required",{body:ui.statusMessage.textContent});if($("sound-review").checked){const ctx=new AudioContext(),osc=ctx.createOscillator(),gain=ctx.createGain();gain.gain.value=.025;osc.frequency.value=660;osc.connect(gain).connect(ctx.destination);osc.start();osc.stop(ctx.currentTime+.12)}}previousReviewState=required}

function renderScorecard(state){const p=state.protocol,e=p.evidence||[],verified=e.length?e.filter(x=>x.verified).length/e.length:0,events=state.events||[],runtime=events.reduce((n,x)=>n+Number(x.duration_ms||0),0),values=[[`${Math.round(verified*100)}%`,"Evidence verified"],[p.revision,"Revision cycles"],[(p.unresolved_risks||[]).length,"Unresolved risks"],[p.ethics.risk_level,"Ethics risk"],[events.length,"Agent events"],[formatDuration(runtime),"Agent runtime"]];$("scorecard-panel").hidden=false;ui.scorecard.innerHTML=values.map(([value,label])=>`<div class="scorecard-item"><strong>${escapeHtml(value)}</strong><span>${escapeHtml(label)}</span></div>`).join("")}
function claimTokens(value){return new Set(String(value||"").toLowerCase().match(/[a-z]{4,}/g)||[])}
function evidenceForClaim(claim,evidence){const tokens=claimTokens(claim);return evidence.map(item=>{const words=claimTokens(`${item.claim} ${item.finding} ${item.title}`),overlap=[...tokens].filter(x=>words.has(x)).length;return {item,score:overlap+Number(item.relevance_score||0)}}).sort((a,b)=>b.score-a.score).slice(0,3).map(x=>x.item)}
function renderTraceability(protocol){const claims=[["Hypothesis",protocol.hypothesis.statement],["Population",protocol.study.population],["Intervention",protocol.study.intervention],["Primary outcome",protocol.study.outcome],["Analysis",protocol.statistics.analysis]];$("traceability-panel").hidden=false;ui.traceability.innerHTML=`<div class="claim-list">${claims.map(([label,value],i)=>`<button data-claim="${i}" aria-selected="${i===0}"><strong>${label}</strong><br><span>${escapeHtml(value)}</span></button>`).join("")}</div><div id="trace-sources"></div>`;const select=index=>{ui.traceability.querySelectorAll("[data-claim]").forEach((b,i)=>b.setAttribute("aria-selected",String(i===index)));const [label,claim]=claims[index],matches=evidenceForClaim(claim,protocol.evidence||[]);$("trace-sources").innerHTML=`<h3>${escapeHtml(label)} support</h3>${matches.length?matches.map(item=>`<article class="trace-source"><strong>${escapeHtml(item.title)}</strong><p>${escapeHtml(item.supporting_passage||item.finding)}</p><span class="badge">Support ${Number(item.entailment_score).toFixed(2)}</span> <span class="badge">Relevance ${Number(item.relevance_score).toFixed(2)}</span></article>`).join(""):'<div class="empty-state"><strong>No directly matched source</strong><span>This claim requires targeted evidence review.</span></div>'}`;track("traceability_view",{claim:label})};ui.traceability.querySelectorAll("[data-claim]").forEach(b=>b.onclick=()=>select(Number(b.dataset.claim)));select(0)}
function renderDisagreements(protocol){const critiques=protocol.critique_history||[],resolved=protocol.revision_history||[];$("disagreement-panel").hidden=false;ui.disagreements.innerHTML=critiques.length?critiques.map((c,i)=>`<article class="disagreement-card"><div><span class="badge">Skeptical reviewer</span><h3>${escapeHtml(c.issue)}</h3><p>${escapeHtml(c.recommendation)}</p></div><div><span class="badge">Protocol council</span><h3>${resolved[i]?"Accepted concern":"Pending resolution"}</h3><p>${escapeHtml(resolved[i]?.reason||"The concern remains visible for human review.")}</p></div><div class="resolution"><strong>Resolution:</strong> ${resolved[i]?`Revision ${resolved[i].revision} incorporated the recommendation.`:"Human decision required."}</div></article>`).join(""):'<div class="empty-state"><strong>No recorded disagreement</strong><span>The specialist reviews converged on the current protocol.</span></div>'}
function firstDraft(protocol){const first=protocol.revision_history?.[0];if(!first)return null;try{const value=JSON.parse(first.before);return value.study?value:{study:value}}catch{return null}}
function renderBeforeAfter(protocol){const draft=firstDraft(protocol),fields=[["Population","population"],["Intervention","intervention"],["Outcome","outcome"],["Duration","duration"]];$("before-after-panel").hidden=false;if(!draft?.study){ui.beforeAfter.innerHTML='<div class="empty-state"><strong>No revision delta yet</strong><span>The current protocol is still its first reviewed draft.</span></div>';return}ui.beforeAfter.innerHTML=`<div class="version-column"><h3>First draft</h3>${fields.map(([l,k])=>`<p><strong>${l}</strong><br><del>${escapeHtml(draft.study[k])}</del></p>`).join("")}</div><div class="version-column"><h3>Current protocol</h3>${fields.map(([l,k])=>`<p><strong>${l}</strong><br><ins>${escapeHtml(protocol.study[k])}</ins></p>`).join("")}</div>`}

let presentationIndex=0;
function presentationSlides(){const p=latest?.state?.protocol,s=latest?.state;if(!p)return[];const evidence=p.evidence||[];return[["The research question",p.question],["A council, not a chatbot",`${new Set((s.events||[]).map(x=>x.node.split(":")[0])).size} specialist stages collaborated through a persistent LangGraph workflow.`],["Grounded evidence",`${evidence.filter(x=>x.verified).length} of ${evidence.length} sources passed citation and claim-support screening.`],["Constructive disagreement",`${(p.critique_history||[]).length} critique${(p.critique_history||[]).length===1?'':'s'} challenged the design; ${p.revision} revision cycle${p.revision===1?'':'s'} strengthened it.`],["Human governance",`Ethics risk: ${p.ethics.risk_level}. ${(p.ethics.required_safeguards||[]).length} safeguard${(p.ethics.required_safeguards||[]).length===1?'':'s'} recorded before approval.`],["Measured workflow outcome","Both systems completed 24 of 24 deterministic drafting tasks with equivalent evidence. ResearchGuard achieved collaboration value on 24 of 24; collaboration is not applicable to a single-agent system."],["The resulting protocol",`${p.study.design} with ${p.statistics.target_sample_size} participants, measuring ${p.study.outcome}.`]]}
function showPresentationStep(){const slides=presentationSlides(),[title,body]=slides[presentationIndex]||[];$("presentation-content").innerHTML=`<div><span class="step-label">Story ${presentationIndex+1}</span><h2>${escapeHtml(title)}</h2><p>${escapeHtml(body)}</p></div>`;$("presentation-step").textContent=`${presentationIndex+1} / ${slides.length}`;$("presentation-back").disabled=presentationIndex===0;$("presentation-next").textContent=presentationIndex===slides.length-1?"Finish":"Next"}
function openPresentation(){if(!latest?.state?.protocol){showToast("Complete a protocol before entering presentation mode.");return}presentationIndex=0;$("presentation").hidden=false;document.body.style.overflow="hidden";showPresentationStep();track("presentation_open")}
function closePresentation(){$("presentation").hidden=true;document.body.style.overflow="";$("presentation-button").focus()}
function advancePresentation(delta){const slides=presentationSlides();if(delta>0&&presentationIndex===slides.length-1)return closePresentation();presentationIndex=Math.max(0,Math.min(slides.length-1,presentationIndex+delta));showPresentationStep()}

function exportJson(){const blob=new Blob([JSON.stringify(latest?.state||{},null,2)],{type:"application/json"}),link=document.createElement("a");link.href=URL.createObjectURL(blob);link.download=`researchguard-${threadId}.json`;link.click();track("export",{format:"json"})}
async function resetWorkspace(){if(!confirm("Delete all runs belonging to the current workspace user? This cannot be undone."))return;try{const response=await request("/api/runs?include_archived=true",{headers:apiHeaders(false)}),runs=await response.json();await Promise.all(runs.map(run=>request(`/api/runs/${run.thread_id}`,{method:"DELETE",headers:apiHeaders(false)})));closeStream();threadId="";latest=null;document.querySelectorAll("main section:not(.intake):not(#recent-panel),#summary-grid,#section-nav").forEach(x=>x.hidden=true);loadRuns();showToast("Workspace reset.");track("workspace_reset",{count:runs.length})}catch(error){showToast(error.message)}}
function track(event,properties={}){const entries=JSON.parse(localStorage.getItem("rg-analytics")||"[]");entries.push({event,properties,timestamp:new Date().toISOString()});localStorage.setItem("rg-analytics",JSON.stringify(entries.slice(-100)))}

const commands=[
  ["Start research council",()=>$("run-button").click()], ["Open recent runs",()=>$("recent-panel").scrollIntoView()],
  ["Enter presentation mode",openPresentation], ["Search this run",()=>{$("run-search").focus()}],
  ["Export Markdown",exportReport], ["Export JSON",exportJson], ["Print or save PDF",()=>window.print()],
  ["Open activity inbox",()=>{$("inbox-dialog").showModal();renderInbox()}], ["Open privacy and data controls",()=>$("privacy-dialog").showModal()], ["Switch simple or expert view",()=>{$("view-mode").value=$("view-mode").value==="simple"?"expert":"simple";applyWorkspaceView()}],
  ["Toggle theme",cycleTheme], ["Toggle high contrast",toggleContrast], ["Reset demo data",resetWorkspace]
];
function openCommands(){$("command-dialog").showModal();$("command-search").value="";renderCommands();setTimeout(()=>$("command-search").focus(),0)}
function renderCommands(){const q=$("command-search").value.toLowerCase(),matches=commands.filter(([label])=>label.toLowerCase().includes(q));$("command-results").innerHTML=matches.map(([label],i)=>`<button role="option" data-command="${i}">${escapeHtml(label)}</button>`).join("")||'<div class="empty-state">No matching commands</div>';$("command-results").querySelectorAll("[data-command]").forEach((b,i)=>b.onclick=()=>{$("command-dialog").close();matches[i][1]();track("command_used",{command:matches[i][0]})})}
function toggleContrast(){const enabled=document.documentElement.dataset.contrast!=="high";document.documentElement.dataset.contrast=enabled?"high":"";$("contrast-button").textContent=`High contrast: ${enabled?'on':'off'}`;localStorage.setItem("rg-contrast",String(enabled))}

function applyWorkspaceView(){const view=$("view-mode").value,role=$("role-select").value;document.documentElement.dataset.view=view;document.documentElement.dataset.role=role;localStorage.setItem("rg-view",view);localStorage.setItem("rg-role",role);const labels={researcher:"Research protocol workspace",ethics:"Ethics and safeguards workspace",statistician:"Statistical review workspace",admin:"Operations and audit workspace"};document.querySelector(".eyebrow").textContent=labels[role];track("workspace_view",{view,role})}
function evidenceKey(item){return item.identifier||item.source||item.title}
function getBookmarks(){return JSON.parse(localStorage.getItem(`rg-bookmarks-${threadId}`)||"[]")}
function toggleBookmark(key){const values=getBookmarks(),index=values.indexOf(key),saved=index<0;if(index>=0)values.splice(index,1);else values.push(key);localStorage.setItem(`rg-bookmarks-${threadId}`,JSON.stringify(values));ui.evidence.querySelectorAll("[data-bookmark]").forEach(button=>{if(button.dataset.bookmark===key){button.setAttribute("aria-pressed",String(saved));button.setAttribute("aria-label",saved?"Remove bookmark":"Bookmark evidence");button.textContent=saved?"★":"☆"}});showToast(saved?"Evidence bookmarked.":"Bookmark removed.")}
function savedFilters(){return JSON.parse(localStorage.getItem("rg-saved-filters")||"[]")}
function refreshSavedFilters(){const filters=savedFilters();$("saved-filters").innerHTML='<option value="">Saved filters</option>'+filters.map((x,i)=>`<option value="${i}">${escapeHtml(x.name)}</option>`).join("")}
function saveCurrentFilter(){const name=prompt("Name this evidence filter:","My evidence view");if(!name)return;const filters=savedFilters();filters.push({name,source:$("source-filter").value,verified:$("verified-filter").value,sort:$("evidence-sort").value});localStorage.setItem("rg-saved-filters",JSON.stringify(filters.slice(-12)));refreshSavedFilters();showToast("Evidence filter saved.")}
function applySavedFilter(){const filter=savedFilters()[Number($("saved-filters").value)];if(!filter)return;$("source-filter").value=filter.source;$("verified-filter").value=filter.verified;$("evidence-sort").value=filter.sort;latest?.state?.protocol&&renderEvidence(latest.state.protocol.evidence||[])}
function commentKey(){return `rg-comments-${threadId}`}
function getComments(){return JSON.parse(localStorage.getItem(commentKey())||"[]")}
function renderComments(){$("review-comments-panel").hidden=false;const comments=getComments();$("comments").innerHTML=comments.length?comments.map((c,i)=>`<article class="comment-thread ${c.resolved?'resolved':''}"><p>${escapeHtml(c.text)}</p><div class="comment-meta">${escapeHtml(c.author)} · ${escapeHtml(c.target)} · ${formatTime(c.created)}</div><button data-resolve-comment="${i}">${c.resolved?'Reopen':'Resolve'}</button></article>`).join(""):'<div class="empty-state"><strong>No review comments</strong><span>Add a targeted note for the next reviewer.</span></div>';$("comments").querySelectorAll("[data-resolve-comment]").forEach(button=>button.onclick=()=>resolveComment(Number(button.dataset.resolveComment)))}
function addComment(){const text=$("comment-text").value.trim();if(!text){showToast("Write a comment before posting.");return}const comments=getComments();comments.push({text,target:$("comment-target").value,author:ui.user.value||"Reviewer",created:new Date().toISOString(),resolved:false});localStorage.setItem(commentKey(),JSON.stringify(comments));$("comment-text").value="";renderComments();addInbox("New review comment",`${$("comment-target").value}: ${text.slice(0,70)}`);track("comment_added",{target:$("comment-target").value})}
function resolveComment(index){const comments=getComments();comments[index].resolved=!comments[index].resolved;localStorage.setItem(commentKey(),JSON.stringify(comments));renderComments()}
function renderReadiness(state){const p=state.protocol||{},e=p.evidence||[],comments=getComments(),checks=[[e.length>0&&e.every(x=>x.verified),"All evidence has passed verification screening"],[(p.unresolved_risks||[]).length===0,"No unresolved protocol risks remain"],[Boolean(p.ethics)&&(!p.ethics.requires_human_review||(p.ethics.required_safeguards||[]).length>0),"Ethics safeguards are documented"],[Boolean(p.statistics?.target_sample_size)&&Boolean(p.statistics?.analysis),"Statistical plan and enrollment are specified"],[comments.every(x=>x.resolved),"All review comments are resolved"]];$("readiness-checklist").innerHTML=`<h3>Approval readiness</h3>${checks.map(([pass,label])=>`<div class="readiness-item ${pass?'pass':'warn'}">${escapeHtml(label)}</div>`).join("")}`}
function getInbox(){return JSON.parse(localStorage.getItem("rg-inbox")||"[]")}
function addInbox(title,body){const items=getInbox(),id=`${threadId}:${title}`;if(items.some(x=>x.id===id))return;items.unshift({id,title,body,created:new Date().toISOString(),read:false});localStorage.setItem("rg-inbox",JSON.stringify(items.slice(0,50)));renderInbox()}
function updateInbox(data,state){if((data.next||[]).some(x=>x.includes("human_review")||x==="human_approval"))addInbox("Review required",state.question||"A protocol is waiting for your decision.");if((state.tool_failures||[]).length)addInbox("Evidence tool needs attention",state.tool_failures.at(-1).error);if(state.status==="complete")addInbox("Protocol completed",state.question||"An approved protocol is ready.")}
function renderInbox(){const items=getInbox();$("inbox-count").textContent=items.filter(x=>!x.read).length;$("inbox-items").innerHTML=items.length?items.map(x=>`<article class="inbox-item"><strong>${escapeHtml(x.title)}</strong><p>${escapeHtml(x.body)}</p><time>${formatTime(x.created)}</time></article>`).join(""):'<div class="empty-state"><strong>Inbox clear</strong><span>Reviews, failures, comments, and completions will appear here.</span></div>'}
function clearInbox(){const items=getInbox().map(x=>({...x,read:true}));localStorage.setItem("rg-inbox",JSON.stringify(items));renderInbox()}
function saveUsability(){const records=JSON.parse(localStorage.getItem("rg-usability")||"[]");records.push({score:Number($("usability-score").value),note:$("usability-note").value.trim(),role:$("role-select").value,view:$("view-mode").value,thread_id:threadId||null,timestamp:new Date().toISOString()});localStorage.setItem("rg-usability",JSON.stringify(records));$("usability-dialog").close();showToast("Usability feedback saved locally.")}
function exportUsability(){const data=localStorage.getItem("rg-usability")||"[]",blob=new Blob([data],{type:"application/json"}),link=document.createElement("a");link.href=URL.createObjectURL(blob);link.download="researchguard-usability-study.json";link.click()}
function recordObservedTimings(state){const model=JSON.parse(localStorage.getItem("rg-timing-model")||"{}");for(const event of state.events||[]){if(event.duration_ms==null)continue;const node=event.node.split(":")[0],entry=model[node]||{total:0,count:0},signature=`${threadId}:${event.timestamp}`;if(entry.signatures?.includes(signature))continue;entry.total+=Number(event.duration_ms);entry.count+=1;entry.signatures=[...(entry.signatures||[]).slice(-19),signature];model[node]=entry}localStorage.setItem("rg-timing-model",JSON.stringify(model))}
function estimateRemainingSeconds(done){const model=JSON.parse(localStorage.getItem("rg-timing-model")||"{}"),remaining=Object.keys(graphNodes).filter(node=>!done.has(node)&&!["ethics_human_review","ethics_revision_editor","human_approval","complete"].includes(node));const milliseconds=remaining.reduce((sum,node)=>{const entry=model[node];return sum+(entry?.count?entry.total/entry.count:1500)},0);return Math.max(1,Math.ceil(milliseconds/1000))}
function browserData(){const data={};for(let i=0;i<localStorage.length;i++){const key=localStorage.key(i);if(key?.startsWith("rg-"))data[key]=JSON.parse(JSON.stringify(localStorage.getItem(key)))}return data}
function exportBrowserData(){const blob=new Blob([JSON.stringify(browserData(),null,2)],{type:"application/json"}),link=document.createElement("a");link.href=URL.createObjectURL(blob);link.download="researchguard-browser-data.json";link.click();track("privacy_export")}
function clearBrowserData(){if(!confirm("Clear all ResearchGuard preferences, bookmarks, comments, inbox items, and local feedback from this browser?"))return;const keys=Object.keys(browserData());keys.forEach(key=>localStorage.removeItem(key));$("privacy-dialog").close();location.reload()}

$("run-button").onclick=()=>startRun(false);$("showcase-button").onclick=()=>startRun(true);$("record-button").onclick=toggleRecording;$("live-button").onclick=toggleLive;
$("settings-toggle").onclick=()=>{const hidden=$("settings").hidden;$("settings").hidden=!hidden;$("settings-toggle").setAttribute("aria-expanded",String(hidden))};
$("technical-toggle").onclick=()=>{technicalNames=!technicalNames;$("technical-toggle").textContent=technicalNames?"Use friendly names":"Show technical names";$("technical-toggle").setAttribute("aria-expanded",String(technicalNames));if(latest)renderGraph(latest,latest.state||{})};
$("source-filter").onchange=$("verified-filter").onchange=$("evidence-sort").onchange=()=>latest?.state?.protocol&&renderEvidence(latest.state.protocol.evidence||[]);
$("open-approve").onclick=()=>openDecision(true);$("open-changes").onclick=()=>openDecision(false);$("submit-approval").onclick=()=>submitDecision(true);$("submit-changes").onclick=()=>submitDecision(false);
document.querySelectorAll("[data-suggestion]").forEach(button=>button.onclick=()=>ui.feedback.value=button.dataset.suggestion);
$("retry-button").onclick=()=>recovery("retry");$("offline-button").onclick=()=>recovery("offline");$("continue-button").onclick=()=>recovery("continue");$("cancel-button").onclick=()=>recovery("cancel");
$("speak-button").onclick=speak;$("export-button").onclick=exportReport;
$("json-export").onclick=exportJson;$("print-export").onclick=()=>{track("export",{format:"print_pdf"});window.print()};$("reset-workspace").onclick=resetWorkspace;
$("view-mode").onchange=applyWorkspaceView;$("role-select").onchange=applyWorkspaceView;$("mobile-workflow").onclick=()=>$("workflow-dialog").showModal();
$("save-filter").onclick=saveCurrentFilter;$("saved-filters").onchange=applySavedFilter;$("add-comment").onclick=addComment;
$("inbox-button").onclick=()=>{$("inbox-dialog").showModal();renderInbox()};$("clear-inbox").onclick=clearInbox;
$("privacy-button").onclick=()=>$("privacy-dialog").showModal();$("export-local-data").onclick=exportBrowserData;$("clear-local-data").onclick=clearBrowserData;
$("usability-button").onclick=()=>$("usability-dialog").showModal();$("save-usability").onclick=saveUsability;$("export-usability").onclick=exportUsability;
$("presentation-button").onclick=openPresentation;$("exit-presentation").onclick=closePresentation;$("presentation-next").onclick=()=>advancePresentation(1);$("presentation-back").onclick=()=>advancePresentation(-1);
$("command-button").onclick=openCommands;$("command-search").oninput=renderCommands;$("contrast-button").onclick=toggleContrast;if(localStorage.getItem("rg-contrast")==="true"){document.documentElement.dataset.contrast="high";$("contrast-button").textContent="High contrast: on"}
$("refresh-runs").onclick=loadRuns;$("show-archived").onchange=loadRuns;$("edit-protocol").onclick=openProtocolEditor;$("save-edits").onclick=saveProtocolEdits;
$("compare-run").onchange=renderRunComparison;$("history-version").onchange=showHistoryVersion;$("run-search").oninput=applyRunFilters;$("unresolved-only").onchange=applyRunFilters;
$("clear-filters").onclick=()=>{$("source-filter").value="all";$("verified-filter").value="all";$("evidence-sort").value="relevance";latest?.state?.protocol&&renderEvidence(latest.state.protocol.evidence||[])};
$("theme-button").onclick=cycleTheme;setTheme(localStorage.getItem("rg-theme")||"system");
for(const id of ["notify-review","sound-review"]){const el=$(id);el.checked=localStorage.getItem(`rg-${id}`)==="true";el.onchange=async()=>{localStorage.setItem(`rg-${id}`,String(el.checked));if(id==="notify-review"&&el.checked&&"Notification" in window)await Notification.requestPermission()}}
function changeZoom(delta){graphZoom=Math.max(.65,Math.min(1.65,delta===0?1:graphZoom+delta));if(latest)renderGraph(latest,latest.state||{})}
$("zoom-in").onclick=()=>changeZoom(.15);$("zoom-out").onclick=()=>changeZoom(-.15);$("zoom-reset").onclick=()=>changeZoom(0);
let drag=null;ui.graph.onpointerdown=e=>{drag={x:e.clientX,y:e.clientY,left:ui.graph.scrollLeft,top:ui.graph.scrollTop};ui.graph.setPointerCapture(e.pointerId)};ui.graph.onpointermove=e=>{if(drag){ui.graph.scrollLeft=drag.left-(e.clientX-drag.x);ui.graph.scrollTop=drag.top-(e.clientY-drag.y)}};ui.graph.onpointerup=()=>drag=null;
const finishOnboarding=()=>{localStorage.setItem("rg-onboarded","true");$("onboarding-dialog").close()};$("finish-onboarding").onclick=finishOnboarding;$("skip-onboarding").onclick=finishOnboarding;
document.querySelectorAll("[data-close-dialog]").forEach(button=>button.onclick=()=>button.closest("dialog").close());
document.addEventListener("visibilitychange",()=>{if(document.hidden)closeStream();else if(threadId&&latest&&!isTerminal(latest))openStream()});
document.addEventListener("keydown",event=>{if((event.metaKey||event.ctrlKey)&&event.key.toLowerCase()==="k"){event.preventDefault();openCommands()}if(event.key==="Escape"&&!$("presentation").hidden)closePresentation();if(!$("presentation").hidden&&event.key==="ArrowRight")advancePresentation(1);if(!$("presentation").hidden&&event.key==="ArrowLeft")advancePresentation(-1)});
$("view-mode").value=localStorage.getItem("rg-view")||"simple";$("role-select").value=localStorage.getItem("rg-role")||"researcher";applyWorkspaceView();setupDemoQuestions();refreshSavedFilters();renderInbox();loadRuns();if(!localStorage.getItem("rg-onboarded"))setTimeout(()=>$("onboarding-dialog").showModal(),150);const resumeId=new URLSearchParams(location.search).get("run");if(resumeId)resumeRun(resumeId);
